      identical(this, other) ||
      other is TextOverlayData &&
          runtimeType == other.runtimeType &&
          text == other.text &&
          anchorX == other.anchorX &&
          anchorY == other.anchorY &&
          fontSize == other.fontSize &&
          fontWeight == other.fontWeight &&
          italic == other.italic &&
          colorR == other.colorR &&
          colorG == other.colorG &&
          colorB == other.colorB &&
          colorA == other.colorA &&
          letterSpacing == other.letterSpacing &&
          maxWidth == other.maxWidth &&
          padding == other.padding &&
          cornerRadius == other.cornerRadius &&
          showBackground == other.showBackground &&
          backgroundR == other.backgroundR &&
          backgroundG == other.backgroundG &&
          backgroundB == other.backgroundB &&
          backgroundA == other.backgroundA &&
          glowIntensity == other.glowIntensity &&
          textAlign == other.textAlign &&
          contentAnimation == other.contentAnimation &&
          contentAnimationDurationMs == other.contentAnimationDurationMs;
}

/// In-memory thumbnail (JPEG/WebP bytes) — no filesystem write.
class ThumbnailBytesOptions {
  final String inputPath;
  final BigInt positionMs;
  final int? width;
  final int? height;
  final ThumbnailFormat format;

  const ThumbnailBytesOptions({
    required this.inputPath,
    required this.positionMs,
    this.width,
    this.height,
    required this.format,
  });

  @override
  int get hashCode =>
      inputPath.hashCode ^
      positionMs.hashCode ^
      width.hashCode ^
      height.hashCode ^
      format.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ThumbnailBytesOptions &&
          runtimeType == other.runtimeType &&
          inputPath == other.inputPath &&
          positionMs == other.positionMs &&
          width == other.width &&
          height == other.height &&
          format == other.format;
}

/// PR #3: per-position status surfaced from the Rust decode pipeline.
enum ThumbnailDecodeStatus {
  /// Frame decoded at or after the requested position. Most common.
  exact,

  /// The demuxer ran out of packets before reaching the requested
  /// position. The thumbnail is the closest decoded keyframe; the
  /// UI should flag it as approximate.
  nearestKeyframe,
}

enum ThumbnailFormat { jpeg, webp }

class ThumbnailOptions {
  final String inputPath;
  final String? outputPath;
  final BigInt positionMs;
  final int? width;
  final int? height;
  final ThumbnailFormat format;

  const ThumbnailOptions({
    required this.inputPath,
    this.outputPath,
    required this.positionMs,
    this.width,
    this.height,
    required this.format,
  });

  @override
  int get hashCode =>
      inputPath.hashCode ^
      outputPath.hashCode ^
      positionMs.hashCode ^
      width.hashCode ^
      height.hashCode ^
      format.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ThumbnailOptions &&
          runtimeType == other.runtimeType &&
          inputPath == other.inputPath &&
          outputPath == other.outputPath &&
          positionMs == other.positionMs &&
          width == other.width &&
          height == other.height &&
          format == other.format;
}

/// Transform channel. Translate values are fractions of output frame size (1.0 = full width/height).
enum TransformProperty { translateX, translateY, scale, rotation, opacity }

/// Sparse transform animation tracks (normalized coordinates).
class TransformTracks {
  final List<AnimationTrack> tracks;

  const TransformTracks({required this.tracks});

  @override
  int get hashCode => tracks.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TransformTracks &&
          runtimeType == other.runtimeType &&
          tracks == other.tracks;
}

enum VideoCodec { h264, hevc }

enum VideoQuality {
